const STORE='stride-demo-v1';
const SEED={workspace:'Northstar Studio',user:{name:'Alex Morgan',email:'alex@example.com'},projects:[{id:'p1',name:'Customer Portal',description:'Customer-facing account and billing experience.',stack:'React · Node.js · PostgreSQL',updated:'Today',status:'In review',sample:true}],models:[{id:'m1',projectId:'p1',name:'Customer portal — production',description:'A customer-facing portal for account management and billing. Sample demonstration model.',created:'2026-10-18',nodes:[{id:'web',name:'Web client',kind:'External entity',icon:'◉',x:7,y:41,data:'Public',entry:'HTTPS requests',notes:'Browser-based customer access.'},{id:'api',name:'API service',kind:'Process',icon:'⌘',x:39,y:29,data:'Confidential',entry:'REST API',notes:'Validates sessions and routes requests.'},{id:'db',name:'Account database',kind:'Data store',icon:'▤',x:69,y:58,data:'Restricted',entry:'SQL connection',notes:'Customer profile and billing records.'},{id:'idp',name:'Identity provider',kind:'External entity',icon:'◇',x:39,y:68,data:'Confidential',entry:'OIDC callback',notes:'External identity provider.'}],flows:[{from:'web',to:'api',label:'HTTPS / JSON'},{from:'api',to:'db',label:'SQL / TLS'},{from:'idp',to:'api',label:'OIDC tokens'}]}],threats:[{id:'T-001',title:'Session token replay',category:'Spoofing',component:'API service',description:'A stolen session token may be replayed to impersonate a legitimate customer.',scenario:'An attacker obtains a token from a compromised client and reuses it before expiry.',impact:'Unauthorized access to browser demo data and actions.',likelihood:3,impactScore:4,severity:'High',status:'Open',owner:'Unassigned',mitigation:'Use short-lived, audience-bound tokens; rotate refresh tokens and detect reuse.',sample:true},{id:'T-002',title:'Unauthorized record modification',category:'Tampering',component:'Account database',description:'An API authorization gap could permit modification of another customer’s records.',scenario:'A caller changes an object identifier in a request and the API fails to verify ownership.',impact:'Customer data integrity loss and incorrect billing state.',likelihood:2,impactScore:5,severity:'High',status:'In Progress',owner:'Alex Morgan',mitigation:'Enforce object-level authorization on every operation; add negative authorization tests.',sample:true},{id:'T-003',title:'Sensitive data in application logs',category:'Information Disclosure',component:'API service',description:'Request logging may include personal or billing details.',scenario:'Operational logs capture full request bodies and are accessible to a broader group.',impact:'Exposure of sensitive customer information.',likelihood:3,impactScore:3,severity:'Medium',status:'Open',owner:'Unassigned',mitigation:'Redact sensitive fields, minimize logged payloads, and define access and retention rules.',sample:true},{id:'T-004',title:'Account actions lack audit trail',category:'Repudiation',component:'API service',description:'Critical account changes may not record who performed the action.',scenario:'A disputed billing change cannot be attributed because actor and request context are missing.',impact:'Reduced incident investigation and accountability.',likelihood:2,impactScore:3,severity:'Medium',status:'Open',owner:'Unassigned',mitigation:'Record actor, timestamp, action, target, and correlation ID in an append-only audit event.',sample:true},{id:'T-005',title:'Resource exhaustion on sign-in',category:'Denial of Service',component:'API service',description:'Unrestricted authentication requests may consume service capacity.',scenario:'Automated repeated requests overwhelm login and downstream identity dependencies.',impact:'Customers may be unable to sign in.',likelihood:2,impactScore:3,severity:'Medium',status:'Open',owner:'Unassigned',mitigation:'Apply adaptive rate limits, request timeouts, and abuse monitoring.',sample:true},{id:'T-006',title:'Excessive API privileges',category:'Elevation of Privilege',component:'API service',description:'The API service account may have broader database permissions than its functions require.',scenario:'A service compromise uses broad database grants to access unrelated data.',impact:'Expanded blast radius from a service-level compromise.',likelihood:2,impactScore:4,severity:'High',status:'Open',owner:'Unassigned',mitigation:'Grant least privilege per service operation; separate read and write roles.',sample:true}],activity:[{text:'Sample workspace and model loaded',time:'Just now'},{text:'Example threat register generated using local demo rules',time:'Just now'}],templates:['Web application','REST API','Authentication service','E-commerce system','Cloud architecture','Microservices','AI-enabled application']};
let state;try{state=JSON.parse(localStorage.getItem(STORE))||structuredClone(SEED)}catch{state=structuredClone(SEED)}

let selectedNode=null, threatFilter='All', threatSearch='', activeModelId='m1';
const save=()=>localStorage.setItem(STORE,JSON.stringify(state));
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const id=prefix=>prefix+'-'+Math.random().toString(36).slice(2,7).toUpperCase();
const toast=msg=>{const t=document.getElementById('toast');t.innerHTML=`<div class="toast">${esc(msg)}</div>`;setTimeout(()=>t.innerHTML='',2800)};
const model=()=>state.models.find(x=>x.id===activeModelId)||state.models[0];
const project=()=>state.projects.find(x=>x.id===model()?.projectId)||state.projects[0];
const sev=n=>n>=16?'Critical':n>=10?'High':n>=5?'Medium':'Low';
const score=t=>Number(t.likelihood||1)*Number(t.impactScore||1);
const log=text=>{state.activity.unshift({text,time:'Just now'});state.activity=state.activity.slice(0,30);save()};
function route(){return (location.hash||'#/').replace(/^#\/?/,'').split('/').filter(Boolean)}
function go(path){location.hash='#/'+path.replace(/^\//,'');}
function brand(){return `<a class="brand" href="#/"><span class="brandmark">N</span>NexGuard</a>`}
function marketingNav(){return `<header class="topnav">${brand()}<nav class="navlinks" id="publicnav" aria-label="Main navigation"><div class="navgroup-wrap"><button class="nav-control" data-action="nav-dropdown" aria-expanded="false" aria-controls="menu-product">Product <span>⌄</span></button><div class="nav-menu" id="menu-product"><a href="#/features"><b>Platform overview</b><small>Architecture, findings, and follow-through</small></a><a href="#/methodology"><b>STRIDE methodology</b><small>Explore the six threat categories</small></a><a href="#/use-cases"><b>Who it’s for</b><small>Developers, architects, and security teams</small></a></div></div><a href="#/use-cases">Use cases</a><a href="#/methodology">Methodology</a><div class="navgroup-wrap"><button class="nav-control" data-action="nav-dropdown" aria-expanded="false" aria-controls="menu-learn">Learn <span>⌄</span></button><div class="nav-menu" id="menu-learn"><a href="#/resources"><b>Resource library</b><small>Guides, examples, and tutorials</small></a><a href="#/security"><b>Data & security</b><small>How this demonstration handles data</small></a><a href="#/contact"><b>Contact</b><small>Send a demo inquiry</small></a></div></div></nav><div class="navright"><a class="btn ghost signin" href="#/accounts">Accounts in progress</a><a class="btn primary" href="#/app/overview">Start threat modeling <span aria-hidden="true">↗</span></a><button class="iconbtn menu-toggle" data-action="menu" aria-label="Open navigation" aria-expanded="false">☰</button></div></header>`}

function footer(){return `<footer class="footer"><div>${brand()}<p style="margin-top:14px">A clear workspace for structured threat modeling.</p><small>Demonstration experience · Sample data is labeled</small></div><div class="footerlinks"><a href="#/features">Platform</a><a href="#/use-cases">Use cases</a><a href="#/methodology">STRIDE guide</a><a href="#/resources">Resources</a><a href="#/security">Data handling</a><a href="#/contact">Contact</a><a href="#/app/overview">Open the demo</a></div></footer>`}
const cats=[['◎','Spoofing','An attacker pretends to be a trusted user or service.','A stolen session token is replayed.'],['⌁','Tampering','Data or code is changed without authorization.','An API request changes another user’s record.'],['≋','Repudiation','An actor can deny an action without reliable evidence.','A sensitive change has no attributable audit event.'],['◈','Information disclosure','Information reaches someone who should not see it.','Personal data appears in broadly accessible logs.'],['⊘','Denial of service','A service or resource becomes unavailable.','Unbounded requests exhaust a login endpoint.'],['⬆','Elevation of privilege','A user gains permissions beyond their role.','A service account has broad database access.']];
function preview(){return `<div class="preview"><div class="previewtop"><span>◈ &nbsp; CUSTOMER PORTAL / PRODUCTION</span><span class="mono">SAMPLE MODEL · SAVED</span></div><div class="previewbody"><div class="diagram"><div class="boundary"><span>TRUST BOUNDARY · APPLICATION</span></div><i class="flow f1"></i><i class="flow f2"></i><i class="flow f3"></i><div class="node n1"><b>◉ Web client</b><small>External entity</small></div><div class="node n2"><b>⌘ API service</b><small>Process · HTTPS</small></div><div class="node n3"><b>▤ Account DB</b><small>Restricted data</small></div><div class="node n4"><b>◇ Identity provider</b><small>External system</small></div></div><aside class="findings"><h4>Example findings <span style="color:var(--muted)">06</span></h4><div class="finding"><span class="badge high">High</span> Session token replay<small>Spoofing · API service</small></div><div class="finding"><span class="badge high">High</span> Record modification<small>Tampering · Account DB</small></div><div class="finding"><span class="badge medium">Medium</span> Sensitive logs<small>Info disclosure · API</small></div></aside></div></div>`}
function landing(){return `${marketingNav()}<main><section class="hero"><div class="hero-copy"><span class="eyebrow">THREAT MODELING FOR REAL SYSTEMS</span><h1>Threat Modeling,<br>Without the Complexity.</h1><p>Discover security threats earlier, understand your application’s attack surface, and turn threat analysis into actionable mitigations with NexGuard.</p><div class="actions"><a class="btn primary" href="#/app/overview">Start threat modeling <span aria-hidden="true">↗</span></a><a class="btn" href="#/features">Explore the platform</a></div><div class="subnote">STRUCTURED · TRACEABLE · BUILT AROUND STRIDE</div><div class="hero-proof"><span>◉ Architecture-aware</span><span>⌘ Human-reviewed</span><span>✓ Actionable</span></div></div>${preview()}</section><section class="section"><div class="section-head"><div><span class="eyebrow">A CLEARER WAY TO REVIEW RISK</span><h2>From system sketch to<br>security action.</h2></div><p>Keep the architecture, findings, risk decisions, and follow-up work connected in one structured workspace.</p></div><div class="grid four"><article class="card"><span class="num">01 / MODEL</span><h3>Map the system</h3><p>Capture components, data classifications, entry points, and trust boundaries.</p></article><article class="card"><span class="num">02 / DISCOVER</span><h3>Review STRIDE threats</h3><p>Use explicit rule-based prompts to surface example risks for human review.</p></article><article class="card"><span class="num">03 / PRIORITIZE</span><h3>Assess the risk</h3><p>Use a transparent likelihood and impact score to guide a team conversation.</p></article><article class="card"><span class="num">04 / MITIGATE</span><h3>Track the work</h3><p>Assign owners, update statuses, and retain a clear link to the affected component.</p></article></div></section><section class="section stride-explorer" id="stride-explorer"><div class="section-head"><div><span class="eyebrow">INTERACTIVE STRIDE EXPLORER</span><h2>Explore a threat, one question at a time.</h2></div><p>Choose a category to see the kind of question it raises. These examples are prompts for review, not an exhaustive analysis.</p></div><div class="explorer-layout"><div class="category-picker" role="tablist" aria-label="STRIDE categories">${cats.map((c,i)=>`<button class="category-tab ${i===0?'active':''}" role="tab" aria-selected="${i===0}" data-stride="${i}"><span>${c[0]}</span><span>${c[1]}</span><span>↗</span></button>`).join('')}</div><article class="explorer-card" id="stride-detail"><div class="explorer-detail"><span class="eyebrow" id="stride-label">CATEGORY 01 / SPOOFING</span><h3 id="stride-title">Can someone pretend to be trusted?</h3><p id="stride-description">An attacker pretends to be a trusted user or service.</p><div class="example-box"><span class="mono muted">EXAMPLE SCENARIO</span><p id="stride-example">A stolen session token is replayed.</p></div><div class="explorer-bottom"><span class="badge medium">ILLUSTRATIVE PROMPT</span><a href="#/methodology" class="text-link">Read the methodology ↗</a></div></div><div class="explorer-side"><div class="eyebrow">ASK THE TEAM</div><p id="stride-question">How do we verify the identity and freshness of each session?</p><button class="btn small" data-action="open-demo-model">See the example model ↗</button></div></article></div></section><section class="section"><div class="section-head"><div><span class="eyebrow">SEE THE WORKFLOW</span><h2>One system. A clear trail of decisions.</h2></div><p>Switch between the stages to understand how an architecture review can move from diagram to action.</p></div><div class="workflow-switch" role="tablist" aria-label="Workflow stage"><button class="workflow-tab active" data-workflow="architecture">01 Architecture</button><button class="workflow-tab" data-workflow="threats">02 Threats</button><button class="workflow-tab" data-workflow="risk">03 Risk review</button><button class="workflow-tab" data-workflow="mitigations">04 Mitigations</button></div><div class="workflow-preview" id="workflow-preview"><div class="workflow-copy"><span class="eyebrow" id="workflow-kicker">START WITH THE SYSTEM</span><h3 id="workflow-title">Make trust visible.</h3><p id="workflow-description">Map processes, external entities, data stores, and the flows between them. Mark where trust changes and what data needs protection.</p><ul id="workflow-points"><li>Editable components and labels</li><li>Data classification and entry points</li><li>Flows connected to the affected system parts</li></ul><a href="#/app/overview" class="btn primary">Explore the workspace ↗</a></div><div class="workflow-mini">${preview()}</div></div></section><section class="section"><div class="section-head"><div><span class="eyebrow">MADE FOR THE REVIEW ROOM</span><h2>Give each role a useful next step.</h2></div><p>Threat modeling works best when people who build, operate, and protect a system can reason from the same picture.</p></div><div class="audience-tabs" role="tablist" aria-label="Audience"><button class="audience-tab active" data-audience="developers">Developers</button><button class="audience-tab" data-audience="security">Security engineers</button><button class="audience-tab" data-audience="architects">Security architects</button><button class="audience-tab" data-audience="devsecops">DevSecOps</button><button class="audience-tab" data-audience="enterprise">Enterprise teams</button></div><div class="audience-panel" id="audience-panel"><div><span class="eyebrow" id="audience-kicker">FOR DEVELOPERS</span><h3 id="audience-title">Turn design questions into engineering work.</h3><p id="audience-description">Capture the component, scenario, and mitigation while implementation details are fresh. Keep follow-up work attached to the threat record.</p><a class="text-link" href="#/use-cases">Explore use cases ↗</a></div><div class="audience-checks" id="audience-checks"><div>✓ Identify entry points and ownership</div><div>✓ Describe a concrete attack scenario</div><div>✓ Track control work through implementation</div></div></div></section><section class="section"><div class="section-head"><div><span class="eyebrow">RISK ASSESSMENT, EXPLAINED</span><h2>Make the assumptions visible.</h2></div><p>Try an illustrative score. Adjust likelihood and impact to see how the example severity changes.</p></div><div class="risk-studio"><div class="risk-controls"><div class="eyebrow">DISCUSSION AID · 1–5 SCALE</div><label for="likelihood-range">Likelihood <output id="likelihood-value">3</output></label><input id="likelihood-range" type="range" min="1" max="5" value="3"><div class="range-hints"><span>Unlikely</span><span>Likely</span></div><label for="impact-range">Impact <output id="impact-value">4</output></label><input id="impact-range" type="range" min="1" max="5" value="4"><div class="range-hints"><span>Limited</span><span>Severe</span></div></div><div class="risk-result"><span class="eyebrow">ILLUSTRATIVE RESULT</span><div class="risk-score"><strong id="risk-score">12</strong><span>/ 25</span><span id="risk-severity" class="badge high">HIGH</span></div><h3 id="risk-title">High discussion priority</h3><p id="risk-copy">Consider a timely mitigation plan and confirm the assumptions with the system owner.</p><small>Score = likelihood × impact. Teams should calibrate severity bands for their context.</small></div><div class="risk-matrix-wrap"><div class="eyebrow">RISK MATRIX</div><div class="matrix" id="landing-matrix">${Array.from({length:25},(_,i)=>{let l=Math.floor(i/5)+1,im=i%5+1,s=l*im>=16?'critical':l*im>=10?'high':l*im>=5?'medium':'low';return `<div class="risk${s} ${l===3&&im===4?'matrix-selected':''}" data-risk-cell="${l}-${im}">${l*im}</div>`}).join('')}</div><div class="range-hints"><span>LOW</span><span>LIKELIHOOD →</span></div></div></div><p class="risk-disclaimer">This is a demonstration scoring model, not an authoritative security assessment. Scores depend on assumptions and should be reviewed by people familiar with the system.</p></section><section class="section"><div class="section-head"><div><span class="eyebrow">A MODEL THAT GROWS WITH YOUR REVIEW</span><h2>Start small. Add detail as you learn.</h2></div><p>NexGuard keeps the first pass approachable while leaving space for a deeper review as the system evolves.</p></div><div class="grid three"><article class="card"><span class="num">01 / SCOPE</span><h3>Choose a boundary</h3><p>Describe the system, environment, and the parts included in this review. Make assumptions explicit.</p></article><article class="card"><span class="num">02 / CONNECT</span><h3>Follow the data</h3><p>Connect the entry points, services, stores, and external dependencies that shape the attack surface.</p></article><article class="card"><span class="num">03 / DECIDE</span><h3>Keep decisions traceable</h3><p>Link risks to components, record why a finding is accepted or mitigated, and revisit when architecture changes.</p></article></div></section><section class="section"><div class="section-head"><div><span class="eyebrow">EXAMPLE SYSTEMS</span><h2>Begin with a familiar shape.</h2></div><a href="#/resources" class="btn">Browse resources ↗</a></div><div class="grid three">${['Web applications','REST APIs & services','Cloud-native systems','Microservices','AI-enabled applications','Enterprise architectures'].map((x,i)=>`<article class="card"><span class="num">0${i+1}</span><h3>${x}</h3><p>Use a blank model or duplicate an illustrative sample template and adapt it to your design.</p><a href="#/app/overview" class="text-link">Open a sample workflow ↗</a></article>`).join('')}</div></section><section class="section faq"><div class="section-head"><div><span class="eyebrow">COMMON QUESTIONS</span><h2>Good to know.</h2></div></div>${faqItems()}</section><section class="section"><div class="callout"><div><span class="eyebrow">MAKE THE FIRST REVIEW COUNT</span><h2 style="margin:10px 0">Build Security Into Your Architecture.</h2><p class="muted">Start identifying threats before they become expensive problems.</p><div class="subnote">Your account saves workspace changes · Email verification is not configured</div></div><a href="#/app/overview" class="btn primary">Create your first threat model ↗</a></div></section></main>${footer()}`}

const plans=[{name:'Free',price:'Not set',desc:'Explore the workflow',features:['Project limits: not configured','Analysis allowance: not configured','Exports: demonstration only']},{name:'Pro',price:'Placeholder',desc:'For individual practitioners',features:['Usage limits: not configured','Risk and mitigation workflow','Export: JSON / CSV demo']},{name:'Team',price:'Placeholder',desc:'For collaborative reviews',features:['Member limits: not configured','Roles: not configured','Collaboration features: planned']},{name:'Enterprise',price:'Contact us',desc:'For organization-wide needs',features:['Deployment options: discuss','Support level: not configured','Contact for a conversation']}];
function priceCards(buttons=true){return plans.map(p=>`<article class="card"><span class="eyebrow">${p.name.toUpperCase()}</span><div class="pricing">${p.price}<small>${p.price==='Contact us'?'':' · placeholder'}</small></div><p>${p.desc}</p><ul class="featurelist">${p.features.map(f=>`<li>— ${f}</li>`).join('')}</ul>${buttons?`<a class="btn ${p.name==='Team'?'primary':''}" style="display:block;text-align:center;margin-top:17px" href="${p.name==='Enterprise'?'#/contact':'#/app/overview'}">${p.name==='Enterprise'?'Contact enterprise':'Get started'}</a>`:''}</article>`).join('')}
function faqItems(){return [['What is threat modeling?','A structured way to identify how a system could be attacked, understand impact, and plan mitigations.'],['What is the STRIDE methodology?','A set of six threat categories: Spoofing, Tampering, Repudiation, Information Disclosure, Denial of Service, and Elevation of Privilege.'],['Who should use NexGuard?','Developers, security engineers, architects, DevSecOps teams, and groups reviewing application designs.'],['Can I model an existing application?','Yes. In this demo, add components and data flows manually or begin with an illustrative template. Import is not configured.'],['How are threats prioritized?','A transparent demonstration score multiplies likelihood by impact on a 1–5 scale. Teams should calibrate criteria and validate assessments.'],['Can I export reports?','The demo can download a generated JSON or CSV file. PDF export is not implemented.'],['How is architecture data handled?','The demo stores workspace data in this browser only. It is not sent to NexGuard or synced across devices. Account registration, cloud backup, and team sharing are in progress.'],['Is NexGuard suitable for teams?','The workflow is designed to support team discussions. Live collaboration, invitations, and authorization are not configured in this demo.']].map(([q,a])=>`<details><summary>${q}</summary><p>${a}</p></details>`).join('')}
function marketingPage(name){let title,desc,body;if(name==='pricing'){title='Straightforward plans, when pricing is ready.';desc='Plan comparison is shown for planning only. No prices, limits, billing, or entitlements are configured.';body=`<div class="notice">Pricing configuration is pending. Monthly and annual pricing are unavailable, so the billing toggle is disabled. Every limit below is marked “Not configured”.</div><div class="grid four" style="margin:20px 0">${priceCards()}</div><div class="panel"><div class="panelhead"><h3>Plan comparison</h3><span class="badge planned">PLACEHOLDER DATA</span></div><div class="tablewrap"><table class="table"><thead><tr><th>Capability</th><th>Free</th><th>Pro</th><th>Team</th><th>Enterprise</th></tr></thead><tbody>${[['Projects','Not configured','Not configured','Not configured','Not configured'],['Analysis allowance','Not configured','Not configured','Not configured','Not configured'],['Collaboration','Not configured','Not configured','Planned','Planned'],['Exports','Demo JSON / CSV','Demo JSON / CSV','Not configured','Not configured'],['Support','Community placeholder','Not configured','Not configured','Not configured']].map(r=>`<tr>${r.map(x=>`<td>${x}</td>`).join('')}</tr>`).join('')}</tbody></table></div></div><section class="section faq" style="padding-left:0;padding-right:0"><h2>Pricing FAQs</h2>${faqItems()}</section>`}else if(name==='features'){title='A connected threat modeling workflow.';desc='Architecture visualization, structured analysis, risk decisions, and mitigation tracking in one place.';body=`<div class="grid two">${[['Architecture visualization','Edit components, flows, classifications, and a sample trust boundary.'],['STRIDE analysis','Run transparent demonstration rules and review suggestions before accepting them.'],['Threat management','Search, filter, assign, edit, accept, dismiss, or resolve threat records.'],['Risk scoring','Use a configurable likelihood × impact matrix and record residual risk.'],['Mitigation planning','Track status, owner, due date, notes, and related threat.'],['Reports & exports','Preview a structured report and download demo JSON or CSV.'],['Collaboration','Comments, invitations, live collaboration, and backend roles are planned.'],['Integrations','No integrations are connected. Setup requires a configured service.']].map((x,i)=>`<article class="card"><span class="num">0${i+1}</span><h3>${x[0]}</h3><p>${x[1]}</p><span class="badge ${i<6?'low':'planned'}" style="margin-top:15px">${i<6?'WORKING IN DEMO':'PLANNED / NOT CONFIGURED'}</span></article>`).join('')}</div>`}else if(name==='methodology'){title='A practical guide to STRIDE.';desc='A repeatable lens for discussing threats across components and trust boundaries.';body=`<div class="card"><h3>Start with boundaries and data flows</h3><p>Threat modeling asks what the system does, what it trusts, what could go wrong, and what the team will do about it. Draw the system context, identify entry points and sensitive data, then review each boundary crossing.</p></div><div class="grid two" style="margin-top:15px">${cats.map(c=>`<article class="card"><div class="category-icon">${c[0]}</div><h3>${c[1]}</h3><p>${c[2]}<br><span class="muted">Example: ${c[3]}</span></p></article>`).join('')}</div><div class="grid four" style="margin-top:15px">${['Describe the system','Map components and flows','Discover and classify threats','Prioritize and mitigate'].map((x,i)=>`<article class="card step"><span class="stepno">${i+1}</span><div><h3>${x}</h3><p>${['Agree scope and important security requirements.','Mark trust boundaries, entry points, and data classification.','Use STRIDE prompts and validate each scenario with system owners.','Assess likelihood and impact, then track decisions and controls.'][i]}</p></div></article>`).join('')}</div><div class="notice" style="margin-top:15px">Risk scores in this demo are prompts for discussion. They are not authoritative security assessments; calibrate your own criteria and record assumptions.</div>`}else if(name==='use-cases'){title='A shared view for every security conversation.';desc='Keep each role focused on the questions they need to answer.';body=`<div class="grid three">${[['Developers','Map implementation details, capture entry points, and turn review notes into actionable work.'],['Security engineers','Review STRIDE coverage, challenge scenarios, and prioritize mitigation backlog.'],['Security architects','Compare trust boundaries and security assumptions across system components.'],['DevSecOps teams','Keep threat records and remediation status visible alongside delivery workflows.'],['Enterprise security teams','Standardize review conversations. Workspace governance and enterprise controls are not configured.']].map((x,i)=>`<article class="card"><span class="num">0${i+1}</span><h3>${x[0]}</h3><p>${x[1]}</p><a class="btn small" style="margin-top:17px" href="#/app/overview">Explore demo ↗</a></article>`).join('')}</div>`}else if(name==='resources'){title='Resources for the next review.';desc='A concise starting point for threat modeling. Some resources are demonstrations or planned.';body=`<input id="resource-search" class="search" placeholder="Search resources…" aria-label="Search resources" style="width:min(420px,100%);margin-bottom:15px"><div id="resource-list" class="grid three">${[['Getting started','guide','A four-step introduction to your first model.'],['Threat modeling guide','guide','Define scope, boundaries, data, and trust assumptions.'],['STRIDE tutorial','tutorial','Practical questions for each threat category.'],['Example threat models','sample','Illustrative web application and REST API models.'],['Product changelog','planned','Changelog will appear here when releases are configured.'],['API documentation','planned','API documentation placeholder. No public API is configured.'],['Support contact','contact','Send a demo inquiry or support question.']].map(x=>`<article class="card resource" data-search="${x.join(' ').toLowerCase()}"><span class="badge ${x[1]==='planned'?'planned':'low'}">${x[1]}</span><h3>${x[0]}</h3><p>${x[2]}</p><a href="${x[1]==='contact'?'#/contact':'#/methodology'}" class="btn small" style="margin-top:13px">Open ↗</a></article>`).join('')}</div>`}else if(name==='security'){title='Data handling and security information.';desc='A transparent description of this demonstration build. Production policies and controls must be configured by the service operator.';body=`<div class="grid two">${[['Data processing','Workspace edits are stored in this browser only using local storage. No account or server database is used, and demo data is not backed up.'],['Access controls','Email registration, sign-in, cloud sync, shared workspaces, and team access controls are in progress and are not available in this demo.'],['Retention & deletion','Demo data remains in this browser until it is cleared from the workspace or browser storage. Clearing browser data can remove it permanently.'],['Responsible disclosure','A security contact channel has not been configured. Use the enterprise contact form for a non-sensitive inquiry; do not submit vulnerabilities there.'],['Deployment options','This version is a static browser demo and does not require a Python server. Account storage and a production backend are still in progress.'],['Privacy & terms','Production privacy and terms documents have not been provided. This page describes demo behavior only.']].map(x=>`<article class="card"><h3>${x[0]}</h3><p>${x[1]}</p></article>`).join('')}</div>`}else{title='Talk with Stride.';desc='Share a little about your security workflow. This demonstration has no email or CRM service configured.';body=`<div class="grid two"><div class="card"><h3>Enterprise capabilities</h3><p>Discuss workspace governance, collaboration, deployment, integrations, and reporting needs. These capabilities require implementation and verification.</p><p style="margin-top:12px">No certifications, compliance claims, or deployment commitments are represented here.</p></div><div class="card"><form class="form" id="contact-form"><label for="cname">Name</label><input id="cname" required minlength="2" placeholder="Your name"><label for="cemail">Work email</label><input id="cemail" type="email" required placeholder="you@company.com"><label for="cmessage">What would you like to discuss?</label><textarea id="cmessage" required minlength="10" placeholder="A short overview of your needs"></textarea><div class="notice">This demo form does not send or store submissions. No message will be transmitted.</div><button class="btn primary" type="submit">Check inquiry form</button><div id="form-status" class="muted" aria-live="polite"></div></form></div></div>`}return `${marketingNav()}<main><section class="section" style="padding-top:76px"><span class="eyebrow">STRIDE / ${name.toUpperCase().replace('-',' ')}</span><div class="section-head" style="margin-top:10px"><div><h1 style="font-size:clamp(38px,5vw,58px);letter-spacing:-.055em;margin:12px 0">${title}</h1><p style="font-size:15px;max-width:680px">${desc}</p></div>${name==='pricing'?'<button class="btn" disabled aria-disabled="true">Monthly / annual · unavailable</button>':''}</div>${body}</section></main>${footer()}`}
const items=[['Overview','overview','⌂'],['Projects','projects','▦'],['Templates','templates','◇'],['Create Model','create-model','＋'],['Architecture','architecture','⌘'],['Threat Analysis','threats','◈'],['Mitigations','mitigations','✓'],['Reports','reports','▤'],['Team Activity','activity','◷'],['Notifications','notifications','◌'],['Integrations','integrations','⌁'],['Members','members','♙'],['Usage & Billing','billing','▧'],['Audit Logs','audit','≋'],['Settings','settings','⚙']];
function appShell(page,body){const active=page||'overview';return `<div class="app"><aside class="sidebar" id="sidebar"><div class="sidebrand">${brand()}</div><button class="workspace-switch" data-action="workspace">${esc(state.workspace)} <span>⌄</span></button><div>${items.slice(0,3).map(i=>sideItem(i,active)).join('')}<div class="navgroup">THREAT MODELING</div>${items.slice(3,8).map(i=>sideItem(i,active)).join('')}<div class="navgroup">COLLABORATION</div>${items.slice(8,10).map(i=>sideItem(i,active)).join('')}<div class="navgroup">MANAGEMENT</div>${items.slice(10).map(i=>sideItem(i,active)).join('')}</div><div class="sidebar-bottom"><button class="sideitem" data-action="account-info">ⓘ &nbsp; Accounts & cloud sync · in progress</button><button class="sideitem" data-action="clear-data">⌫ &nbsp; Reset workspace data</button></div></aside><section class="appmain"><header class="apptop"><div style="display:flex;align-items:center;gap:12px"><button class="iconbtn mobilebar" data-action="sidebar" aria-label="Open sidebar">☰</button><span class="crumb">${esc(state.workspace)} <span style="color:#586170">/</span> ${esc(pageTitle(active))}</span></div><div class="toptools"><input class="search" id="global-search" placeholder="⌕  Search threats…" aria-label="Search threats"><button class="iconbtn" data-nav="notifications" aria-label="Notifications">♧</button><button class="avatar" data-action="profile" title="Profile">${esc((state.user.name||'A').split(' ').map(x=>x[0]).join('').slice(0,2))}</button></div></header><main class="content">${body}</main></section></div>`}
function sideItem(i,active){return `<button class="sideitem ${active===i[1]?'active':''}" data-nav="${i[1]}"><span style="width:17px">${i[2]}</span>${i[0]}</button>`}
function pageTitle(id){return items.find(i=>i[1]===id)?.[0]||'Overview'}
function head(title,sub,actions=''){return `<div class="pagehead"><div><h1>${title}</h1><p>${sub}</p></div><div class="toolbar">${actions}</div></div>`}
function demoLabel(){return '<span class="badge medium">BROWSER DEMO</span>'}
function overview(){let counts=['Critical','High','Medium','Low'].map(s=>[s,state.threats.filter(t=>t.severity===s&&t.status!=='Dismissed').length]);return `${head(`Good ${greeting()}, ${esc(state.user.name.split(' ')[0])}.`,'Here’s the current picture for your workspace.',`<button class="btn primary" data-action="create-model">＋ Create threat model</button>`)}<div class="notice" style="margin-bottom:15px">Browser demo · Changes are saved only in this browser. Cloud sync and team workspaces are in progress. ${demoLabel()}</div><div class="statgrid"><div class="stat"><label>Threat models</label><strong>${state.models.length}</strong><small>${state.projects.length} projects · saved in this browser</small></div><div class="stat"><label>Open threats</label><strong>${state.threats.filter(t=>!['Resolved','Dismissed','Accepted'].includes(t.status)).length}</strong><small>Across current workspace</small></div><div class="stat"><label>High / critical</label><strong style="color:var(--red)">${state.threats.filter(t=>['High','Critical'].includes(t.severity)&&!['Resolved','Dismissed','Accepted'].includes(t.status)).length}</strong><small>Requires team review</small></div><div class="stat"><label>Open mitigations</label><strong>${state.threats.filter(t=>t.status==='Open'||t.status==='In Progress').length}</strong><small>Not resolved or verified</small></div></div><div class="grid two"><div class="panel"><div class="panelhead"><h3>Recent projects</h3><button class="btn small" data-nav="projects">All projects ↗</button></div><div class="tablewrap"><table class="table"><thead><tr><th>Project</th><th>Status</th><th>Updated</th></tr></thead><tbody>${state.projects.length?state.projects.map(p=>`<tr data-project="${p.id}"><td><span class="title">${esc(p.name)}</span><br><span class="muted">${esc(p.stack||'No stack added')}</span></td><td><span class="badge low">${esc(p.status||'Active')}</span></td><td>${esc(p.updated||'Just now')}</td></tr>`).join(''):'<tr><td colspan="3" class="empty">No projects yet. Create a project to begin.</td></tr>'}</tbody></table></div></div><div class="panel"><div class="panelhead"><h3>Threats by severity</h3><span class="muted" style="font-size:10px">DEMO RECORDS</span></div><div class="panelbody">${counts.map(([s,n])=>`<div style="display:flex;align-items:center;gap:10px;margin:15px 0;font-size:11px"><span class="badge ${s.toLowerCase()}">${s}</span><div style="height:6px;flex:1;background:#2a303a;border-radius:99px"><div style="height:6px;width:${state.threats.length?Math.max(n/state.threats.length*100,n?6:0):0}%;background:${s==='Critical'||s==='High'?'var(--red)':s==='Medium'?'var(--amber)':'var(--green)'};border-radius:99px"></div></div><b>${n}</b></div>`).join('')}<p class="muted" style="font-size:10px">Example-only overview. Scores are discussion prompts, not verified assessments.</p></div></div></div><div class="grid two" style="margin-top:14px"><div class="panel"><div class="panelhead"><h3>Recent activity</h3><button class="btn small" data-nav="activity">View activity ↗</button></div><div class="panelbody">${state.activity.slice(0,5).map(a=>`<div style="padding:10px 0;border-bottom:1px solid var(--border);font-size:11px">◦ &nbsp; ${esc(a.text)} <span class="muted">· ${esc(a.time)}</span></div>`).join('')}</div></div><div class="panel"><div class="panelhead"><h3>Start from a template</h3><span class="badge planned">SAMPLE</span></div><div class="panelbody"><div class="grid two">${['Web application','REST API','Authentication service','Cloud architecture'].map(t=>`<button class="btn small" data-template="${t}">＋ ${t}</button>`).join('')}</div></div></div></div>`}
function greeting(){let h=new Date().getHours();return h<12?'morning':h<18?'afternoon':'evening'}
function projectsPage(){return `${head('Projects','Organize threat models by product or system.',`<button class="btn primary" data-action="new-project">＋ New project</button>`)}<div class="filterbar"><input class="search" id="project-search" placeholder="Search projects…"><select class="select" id="project-sort"><option value="recent">Recently updated</option><option value="name">Name A–Z</option></select></div><div class="grid three" id="project-grid">${state.projects.map(p=>`<article class="card project-card" data-name="${esc(p.name.toLowerCase())}"><div style="display:flex;justify-content:space-between"><span class="badge low">${esc(p.status||'Active')}</span><button class="iconbtn" data-project-menu="${p.id}" aria-label="Project actions">···</button></div><h3>${esc(p.name)}</h3><p>${esc(p.description||'No description added.')}</p><div class="mono muted" style="margin:14px 0">${esc(p.stack||'TECH STACK NOT SET')}</div><div style="border-top:1px solid var(--border);padding-top:13px;display:flex;justify-content:space-between;align-items:center"><span class="muted" style="font-size:10px">${state.models.filter(m=>m.projectId===p.id).length} model(s) · ${esc(p.updated||'Recently')}</span><button class="btn small" data-project-open="${p.id}">Open project ↗</button></div></article>`).join('')||`<div class="panel empty" style="grid-column:1/-1">No projects yet. Create your first project to get started.<br><button class="btn primary" style="margin-top:14px" data-action="new-project">Create project</button></div>`}</div>`}
function templatesPage(){return `${head('Templates','Illustrative starting points. Duplicate to create an editable model.',`<span class="badge medium">SAMPLE ARCHITECTURES</span>`)}<div class="grid three">${state.templates.map((x,i)=>`<article class="card"><span class="num">TEMPLATE / ${String(i+1).padStart(2,'0')}</span><h3>${esc(x)}</h3><p>Example components, data flows, and sample threat prompts. Review and adapt before using in a real assessment.</p><button class="btn small" style="margin-top:15px" data-template="${esc(x)}">Preview & duplicate</button></article>`).join('')}</div>`}
function createModelPage(){return `${head('Create a threat model','Choose a starting point and set the system context.') }<div class="grid three">${[['Start from scratch','Build the model from a blank canvas.','blank'],['Use a template','Duplicate an example architecture and findings.','template'],['Describe the system','Provide a system description and create a scoped model record.','describe']].map(x=>`<article class="card"><span class="num">＋</span><h3>${x[0]}</h3><p>${x[1]}</p><button class="btn primary" style="margin-top:17px" data-create-mode="${x[2]}">Continue ↗</button></article>`).join('')}</div><p class="muted" style="font-size:11px;margin-top:15px">Import from architecture files is not configured. Analysis is a disclosed deterministic demo, not AI.</p>`}
function architecturePage(){const m=model();if(!m)return `${head('Architecture','Create a model first.')}<div class="empty">No model to edit. <button class="btn primary" data-nav="create-model">Create model</button></div>`;let n=m.nodes.find(x=>x.id===selectedNode)||m.nodes[0];selectedNode=n?.id||null;const nodes=m.nodes.map(x=>`<div class="canvas-node ${x.id===selectedNode?'selected':''}" data-node="${x.id}" style="left:${x.x}%;top:${x.y}%" draggable="true"><div class="nodeicon">${x.icon||'◇'}</div><strong>${esc(x.name)}</strong><small>${esc(x.kind)}</small></div>`).join('');const lines=m.flows.map(f=>{let a=m.nodes.find(x=>x.id===f.from),b=m.nodes.find(x=>x.id===f.to);if(!a||!b)return'';return `<line x1="${a.x+5.5}%" y1="${a.y+5}%" x2="${b.x+5.5}%" y2="${b.y+5}%"><title>${esc(f.label)}</title></line>`}).join('');return `${head(esc(m.name),'Edit components, trust boundary details, and flows. Changes are saved in this browser.',`<select class="select" id="model-switch" aria-label="Choose threat model">${[m,...state.models.filter(x=>x.id!==m.id)].map(x=>`<option value="${x.id}">${esc(x.name)}</option>`).join("")}</select><button class="btn" data-action="add-flow">↗ Add flow</button><button class="btn" data-action="add-boundary">◇ Boundary</button><button class="btn" data-action="save-model">✓ Save</button><button class="btn" data-nav="reports">⇩ Export / report</button><button class="btn primary" data-action="analyze">✦ Analyze threats</button>`)}<div class="notice" style="margin-bottom:13px">DEMO RULES · Results below are deterministic example suggestions based on STRIDE prompts. Review and validate each finding; no AI service is configured.</div><div class="editor"><aside class="toolbox"><h3>COMPONENT LIBRARY</h3>${[['＋','Process'],['◉','External entity'],['▤','Data store'],['↗','Data flow']].map(x=>`<div class="component" data-add-node="${x[1]}">${x[0]} &nbsp; ${x[1]}</div>`).join('')}<div class="mono muted" style="margin-top:13px">DRAG NODES TO REPOSITION</div></aside><div class="canvas" id="canvas"><svg class="canvas-svg" viewBox="0 0 100 100" preserveAspectRatio="none"><defs><marker id="arrow" markerWidth="7" markerHeight="7" refX="5" refY="3.5" orient="auto"><polygon points="0 0, 7 3.5, 0 7" fill="#b8f36b"/></marker></defs>${lines}</svg><div class="canvas-boundary"></div>${nodes}</div><aside class="inspector"><h3>COMPONENT INSPECTOR</h3>${n?`<label for="node-name">Name</label><input id="node-name" value="${esc(n.name)}"><label for="node-type">Type</label><select id="node-type">${['Process','External entity','Data store'].map(x=>`<option ${n.kind===x?'selected':''}>${x}</option>`).join('')}</select><label for="node-data">Data classification</label><select id="node-data">${['Public','Internal','Confidential','Restricted'].map(x=>`<option ${n.data===x?'selected':''}>${x}</option>`).join('')}</select><label for="node-entry">Entry point / interface</label><input id="node-entry" value="${esc(n.entry||'')}"><label for="node-notes">Notes</label><textarea id="node-notes">${esc(n.notes||'')}</textarea><button class="btn small" style="margin-top:11px" data-action="save-node">Save component</button><button class="btn small" style="margin:11px 0 0 6px;color:var(--red)" data-action="delete-node">Delete</button>`:`<p>Select a component on the canvas or add a new one.</p>`}</aside></div><div class="panel" style="margin-top:13px"><div class="panelhead"><h3>Data flows</h3><button class="btn small" data-action="add-flow">＋ Add data flow</button></div><div class="panelbody flow-list">${m.flows.map((f,i)=>`<div class="flow-row"><span>${esc(m.nodes.find(n=>n.id===f.from)?.name||'?')} <span style="color:var(--accent)">→</span> ${esc(m.nodes.find(n=>n.id===f.to)?.name||'?')}</span><span class="muted">${esc(f.label)}</span><button class="iconbtn" data-delete-flow="${i}" aria-label="Delete data flow">×</button></div>`).join('')||'<div class="muted">No flows yet.</div>'}</div></div>`}
function threatRows(threats){return threats.map(t=>`<tr data-threat="${t.id}" tabindex="0"><td><span class="title">${esc(t.title)}</span><br><span class="mono muted">${esc(t.id)} ${t.sample?'· SAMPLE':''}</span></td><td>${esc(t.category)}</td><td>${esc(t.component)}</td><td><span class="badge ${t.severity.toLowerCase()}">${esc(t.severity)}</span></td><td>${score(t)}/25</td><td><span class="badge ${t.status==='Implemented'||t.status==='Verified'?'low':t.status==='In Progress'?'medium':''}">${esc(t.status)}</span></td><td>${esc(t.owner||'Unassigned')}</td></tr>`).join('')}
function threatsPage(){let data=state.threats.filter(t=>(threatFilter==='All'||t.severity===threatFilter||t.category===threatFilter||t.status===threatFilter)&&(`${t.title} ${t.component} ${t.category} ${t.id}`.toLowerCase().includes(threatSearch.toLowerCase())));return `${head('Threat analysis','Review findings, assumptions, risk, and ownership.',`<button class="btn" data-action="export-csv">⇩ Export CSV</button><button class="btn primary" data-action="new-threat">＋ Add threat</button>`)}<div class="statgrid">${['Critical','High','Medium','Low'].map(s=>`<div class="stat"><label>${s} severity</label><strong style="${['Critical','High'].includes(s)?'color:var(--red)':s==='Medium'?'color:var(--amber)':'color:var(--green)'}">${state.threats.filter(t=>t.severity===s&&t.status!=='Dismissed').length}</strong><small>Example assessment</small></div>`).join('')}</div><div class="panel"><div class="panelhead"><h3>Threat register <span class="muted">(${data.length})</span></h3><span class="muted" style="font-size:10px">SCORE = LIKELIHOOD × IMPACT (1–5)</span></div><div class="panelbody"><div class="filterbar"><input id="threat-search" class="search" placeholder="Search threats…" value="${esc(threatSearch)}"><select id="threat-filter" class="select"><option>All</option>${['Critical','High','Medium','Low','Open','In Progress','Implemented','Accepted','Verified','Resolved','Dismissed',...cats.map(c=>c[1])].map(x=>`<option ${threatFilter===x?'selected':''}>${x}</option>`).join('')}</select><select id="threat-sort" class="select"><option value="risk">Sort: highest risk</option><option value="name">Sort: title</option></select></div><div class="tablewrap"><table class="table"><thead><tr><th>Threat</th><th>STRIDE</th><th>Component</th><th>Severity</th><th>Risk</th><th>Status</th><th>Owner</th></tr></thead><tbody>${data.length?threatRows(data):'<tr><td colspan="7" class="empty">No threats match this view.</td></tr>'}</tbody></table></div></div></div><div class="grid two" style="margin-top:13px"><div class="panel"><div class="panelhead"><h3>STRIDE distribution</h3><span class="badge medium">SAMPLE DATA</span></div><div class="panelbody">${cats.map(c=>{let count=state.threats.filter(t=>t.category===c[1]&&t.status!=='Dismissed').length;return `<div style="display:flex;justify-content:space-between;border-bottom:1px solid var(--border);padding:9px 0;font-size:11px"><span>${c[0]} ${c[1]}</span><b>${count}</b></div>`}).join('')}</div></div><div class="panel"><div class="panelhead"><h3>Risk scoring</h3></div><div class="panelbody"><p class="muted" style="font-size:12px;line-height:1.65">Likelihood (1–5) × impact (1–5) = score (1–25). Severity bands: Low 1–4, Medium 5–9, High 10–15, Critical 16–25. This illustrative scale is configurable and should be calibrated to your organization.</p><div class="matrix">${Array.from({length:25},(_,i)=>{let l=Math.floor(i/5)+1,im=i%5+1,s=sev(l*im).toLowerCase();return `<div class="risk${s}">${l*im}</div>`}).join('')}</div></div></div></div>`}
function mitigationsPage(){let arr=state.threats.filter(t=>!['Dismissed'].includes(t.status));return `${head('Mitigation backlog','Track control work linked to each threat.',`<button class="btn" data-nav="threats">Review threat register</button>`)}<div class="notice" style="margin-bottom:14px">Suggested controls are illustrative guidance. Validate them against the system and applicable requirements.</div><div class="panel"><div class="panelhead"><h3>Mitigation work</h3><span class="muted">${arr.length} item(s)</span></div><div class="tablewrap"><table class="table"><thead><tr><th>Threat & control</th><th>Priority</th><th>Owner</th><th>Status</th><th>Update status</th></tr></thead><tbody>${arr.map(t=>`<tr><td><span class="title">${esc(t.title)}</span><br><span class="muted">${esc(t.mitigation)}</span></td><td><span class="badge ${t.severity.toLowerCase()}">${esc(t.severity)}</span></td><td>${esc(t.owner||'Unassigned')}</td><td>${esc(t.status)}</td><td><select class="select status-change" data-status-id="${t.id}">${['Open','In Progress','Implemented','Accepted','Verified','Resolved'].map(s=>`<option ${t.status===s?'selected':''}>${s}</option>`).join('')}</select></td></tr>`).join('')||'<tr><td colspan="5" class="empty">No mitigation items.</td></tr>'}</tbody></table></div></div>`}
function reportsPage(){let active=state.threats.filter(t=>!['Dismissed','Resolved'].includes(t.status));return `${head('Reports','Preview a structured summary, then download supported JSON or CSV formats.',`<button class="btn" data-action="export-json">⇩ Download JSON</button><button class="btn" data-action="export-csv">⇩ Download CSV</button>`)}<div class="notice" style="margin-bottom:14px">Exports are generated in your browser from the current browser workspace data. PDF generation is not implemented.</div><div class="panel report"><div class="panelhead"><h3>Report preview · ${esc(model()?.name||'No model')}</h3><span class="mono muted">GENERATED ${new Date().toLocaleDateString()}</span></div><div class="panelbody"><span class="badge medium">DEMO REPORT</span><h2 style="font-size:23px">${esc(project()?.name||'Workspace')} — Threat Model Summary</h2><p class="muted">System scope: ${esc(model()?.description||'No scope defined')}<br>Workspace: ${esc(state.workspace)} · Model ID: ${esc(model()?.id||'—')} · Report date: ${new Date().toLocaleDateString()}</p><h3>Executive summary</h3><p>There are ${active.length} active example findings. ${active.filter(t=>['Critical','High'].includes(t.severity)).length} are currently rated High or Critical under the configurable demonstration scoring model. Findings require review by system owners.</p><h3>Architecture overview</h3><p>${model()?.nodes?.length||0} components and ${model()?.flows?.length||0} data flows are in the current model. Trust boundary and component details should be verified with the engineering team.</p><h3>Threat register</h3><div class="tablewrap"><table class="table"><thead><tr><th>ID / Threat</th><th>Category</th><th>Component</th><th>Severity</th><th>Status</th></tr></thead><tbody>${active.map(t=>`<tr><td>${esc(t.id)} · ${esc(t.title)}</td><td>${esc(t.category)}</td><td>${esc(t.component)}</td><td><span class="badge ${t.severity.toLowerCase()}">${esc(t.severity)}</span></td><td>${esc(t.status)}</td></tr>`).join('')}</tbody></table></div><h3>Mitigation recommendations</h3><ul>${active.map(t=>`<li><b>${esc(t.title)}:</b> ${esc(t.mitigation)}</li>`).join('')}</ul><h3>Method and limitations</h3><p>This report is generated in your browser from browser demo data and clearly labeled examples. Risk score is likelihood × impact on a 1–5 scale. Suggestions are not AI generated and are not a security certification or exhaustive assessment.</p></div></div>`}
function activityPage(){return `${head('Demo activity','Recent changes in this browser workspace.',`<span class="badge low">LOCAL HISTORY</span>`)}<div class="panel"><div class="panelhead"><h3>Activity feed</h3></div><div class="panelbody">${state.activity.map(a=>`<div style="padding:13px 0;border-bottom:1px solid var(--border);font-size:12px">◦ &nbsp; ${esc(a.text)} <span class="muted">· ${esc(a.time)}</span></div>`).join('')}</div></div>`}
function settingsPage(){return head('Settings','Preferences for this browser demo.','<button class="btn primary" data-action="save-settings">Save changes</button>')+'<div class="grid two"><div class="panel"><div class="panelhead"><h3>Demo profile</h3><span class="badge medium">LOCAL ONLY</span></div><div class="panelbody form"><label>Display name</label><input id="setting-name" value="'+esc(state.user.name)+'"><p class="muted">This label is stored in this browser only. There is no user account or email sign-in yet.</p></div></div><div class="panel"><div class="panelhead"><h3>Workspace</h3></div><div class="panelbody form"><label>Workspace name</label><input id="setting-workspace" value="'+esc(state.workspace)+'"><p class="muted">Your projects and threat models are saved in this browser local storage. They do not sync to other devices.</p></div></div><div class="panel"><div class="panelhead"><h3>In progress</h3></div><div class="panelbody"><div class="checklist"><div class="checkrow"><span class="badge planned">IN PROGRESS</span> Email registration and sign-in</div><div class="checkrow"><span class="badge planned">IN PROGRESS</span> Cloud backup and cross-device sync</div><div class="checkrow"><span class="badge planned">PLANNED</span> Team workspaces and invitations</div></div></div></div><div class="panel"><div class="panelhead"><h3>Usage &amp; billing</h3><span class="badge planned">NOT CONFIGURED</span></div><div class="panelbody"><p class="muted" style="font-size:12px">No subscription, billing, usage metering, or payment integration is available.</p><a href="#/pricing" class="btn small">View plan information ↗</a></div></div></div>'}
function unavailablePage(page){const descriptions={notifications:'No notification service is connected. This area has no unread messages in demo mode.',integrations:'No external integrations are connected. Setup instructions depend on the service being configured.',members:'Team invitations, role management, and backend authorization are not configured.',billing:'Plan prices, usage limits, subscription state, and payments are not configured.',audit:'A local activity feed is available; tamper-resistant server-side audit logs are not configured.'};return `${head(pageTitle(page),descriptions[page]||'This capability is not configured in the demonstration.') }<div class="panel empty"><span class="badge planned">NOT CONFIGURED</span><p>${descriptions[page]}</p><a class="btn" href="#/resources">See demo resources ↗</a></div>`}
function openThreat(idval){const t=state.threats.find(x=>x.id===idval);if(!t)return;showModal(`<div class="modalhead"><div><span class="eyebrow">${esc(t.id)} · ${esc(t.category.toUpperCase())}</span><h2>${esc(t.title)}</h2><p>Affected component: ${esc(t.component)}</p></div><button class="iconbtn" data-action="close-modal">×</button></div><form class="form" id="threat-edit" data-id="${t.id}"><div class="formgrid"><div><label>Title</label><input name="title" required value="${esc(t.title)}"></div><div><label>STRIDE category</label><select name="category">${cats.map(c=>`<option ${t.category===c[1]?'selected':''}>${c[1]}</option>`).join('')}</select></div><div><label>Affected component</label><select name="component">${(model()?.nodes||[]).map(n=>`<option ${t.component===n.name?'selected':''}>${esc(n.name)}</option>`).join('')}<option ${!model()?.nodes.some(n=>n.name===t.component)?'selected':''}>${esc(t.component)}</option></select></div><div><label>Owner</label><input name="owner" value="${esc(t.owner)}" placeholder="Unassigned"></div><div><label>Likelihood (1–5)</label><select name="likelihood">${[1,2,3,4,5].map(n=>`<option ${Number(t.likelihood)===n?'selected':''}>${n}</option>`).join('')}</select></div><div><label>Impact (1–5)</label><select name="impactScore">${[1,2,3,4,5].map(n=>`<option ${Number(t.impactScore)===n?'selected':''}>${n}</option>`).join('')}</select></div><div><label>Status</label><select name="status">${['Open','In Progress','Implemented','Accepted','Verified','Resolved','Dismissed'].map(s=>`<option ${t.status===s?'selected':''}>${s}</option>`).join('')}</select></div><div><label>Computed score / severity</label><div class="pill" id="score-label">${score(t)} / 25 · ${t.severity}</div></div></div><label>Description</label><textarea name="description" required>${esc(t.description)}</textarea><label>Attack scenario</label><textarea name="scenario">${esc(t.scenario)}</textarea><label>Potential impact</label><textarea name="impact">${esc(t.impact)}</textarea><label>Suggested mitigation</label><textarea name="mitigation">${esc(t.mitigation)}</textarea><div class="modalactions"><button type="button" class="btn" data-action="dismiss-threat" data-id="${t.id}">Dismiss</button><button class="btn primary" type="submit">Save threat</button></div></form>`)}
function showModal(content){let b=document.createElement('div');b.className='modalback';b.id='modalback';b.innerHTML=`<section class="modal" role="dialog" aria-modal="true">${content}</section>`;document.body.append(b);b.addEventListener('click',e=>{if(e.target===b)b.remove()});}
function formModal(title,subtitle,fields,submitLabel,action){showModal(`<div class="modalhead"><div><h2>${title}</h2><p>${subtitle}</p></div><button class="iconbtn" data-action="close-modal">×</button></div><form class="form" id="generic-form" data-form-action="${action}">${fields}<div class="modalactions"><button type="button" class="btn" data-action="close-modal">Cancel</button><button class="btn primary" type="submit">${submitLabel}</button></div></form>`)}
function accountProgressPage(){return marketingNav()+'<main><section class="section" style="min-height:65vh;display:grid;place-items:center"><article class="card" style="max-width:650px;text-align:center;padding:clamp(28px,6vw,56px)"><span class="eyebrow">COMING SOON</span><h1 style="font-size:clamp(30px,5vw,46px);margin:18px 0">Accounts are in progress</h1><p>Email sign-in, cloud-saved workspaces, and team accounts are being developed. For now, explore NexGuard without registering. Demo changes are saved only in this browser and are not backed up.</p><div class="actions" style="justify-content:center"><a class="btn primary" href="#/app/overview">Explore the demo ↗</a><a class="btn" href="#/">Back home</a></div></article></section></main>'+footer()}
function render(){let r=route(),first=r[0]||'';const appPages=['overview','projects','templates','create-model','architecture','threats','mitigations','reports','activity','notifications','integrations','members','billing','audit','settings'];if(!first){document.getElementById('app').innerHTML=landing();document.title='NexGuard — Threat modeling, without the complexity';return}if(['accounts','signin','signup','verify','forgot','reset','onboarding'].includes(first)){document.getElementById('app').innerHTML=accountProgressPage();document.title='Accounts in progress · NexGuard';return}if(['pricing','features','use-cases','methodology','resources','security','contact'].includes(first)){document.getElementById('app').innerHTML=marketingPage(first);document.title=`${first[0].toUpperCase()+first.slice(1)} · NexGuard`;return}if(first==='app')first=r[1]||'overview';if(!appPages.includes(first)){document.getElementById('app').innerHTML=landing();return}activeModelId=state.models.some(m=>m.id===activeModelId)?activeModelId:state.models[0]?.id;let body=({overview,projects:projectsPage,templates:templatesPage,'create-model':createModelPage,architecture:architecturePage,threats:threatsPage,mitigations:mitigationsPage,reports:reportsPage,activity:activityPage,settings:settingsPage})[first]?.()||unavailablePage(first);document.getElementById('app').innerHTML=appShell(first,body);document.title=`${pageTitle(first)} · NexGuard`}
function download(name,type,data){let blob=new Blob([data],{type}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),500)}
function csv(){let rows=[['ID','Title','Category','Component','Description','Attack scenario','Impact','Likelihood','Impact score','Risk score','Severity','Status','Owner','Mitigation'],...state.threats.map(t=>[t.id,t.title,t.category,t.component,t.description,t.scenario,t.impact,t.likelihood,t.impactScore,score(t),t.severity,t.status,t.owner,t.mitigation])];return rows.map(r=>r.map(x=>'"'+String(x??'').replaceAll('"','""')+'"').join(',')).join('\r\n')}
function createProject(){formModal('Create project','Organize the system and its models.',`<label>Project name</label><input name="name" required minlength="2" placeholder="e.g. Customer portal"><label>Description</label><textarea name="description" placeholder="What does this system do?"></textarea><label>Technology stack</label><input name="stack" placeholder="e.g. React · Node.js · PostgreSQL">`,'Create project','project')}
function createThreat(){let comps=model()?.nodes.map(n=>`<option>${esc(n.name)}</option>`).join('')||'';formModal('Add threat','Record a scenario and a first-pass risk assessment.',`<div class="formgrid"><div><label>Threat title</label><input name="title" required placeholder="Short, specific title"></div><div><label>STRIDE category</label><select name="category">${cats.map(c=>`<option>${c[1]}</option>`).join('')}</select></div><div><label>Affected component</label><select name="component">${comps}<option>System level</option></select></div><div><label>Owner</label><input name="owner" placeholder="Unassigned"></div><div><label>Likelihood (1–5)</label><select name="likelihood">${[1,2,3,4,5].map(n=>`<option ${n===2?'selected':''}>${n}</option>`).join('')}</select></div><div><label>Impact (1–5)</label><select name="impactScore">${[1,2,3,4,5].map(n=>`<option ${n===3?'selected':''}>${n}</option>`).join('')}</select></div></div><label>Description</label><textarea name="description" required></textarea><label>Attack scenario</label><textarea name="scenario" required></textarea><label>Potential impact</label><textarea name="impact"></textarea><label>Suggested mitigation</label><textarea name="mitigation"></textarea>`,'Add threat','threat')}
document.addEventListener('click',e=>{const el=e.target.closest('[data-action],[data-nav],[data-threat],[data-template],[data-create-mode],[data-node],[data-project-open],[data-project-menu],[data-delete-flow]');if(!el)return;if(el.dataset.nav){go(el.dataset.nav);document.getElementById('sidebar')?.classList.remove('open');return}if(el.dataset.action){let a=el.dataset.action;if(a==='menu')document.getElementById('publicnav')?.classList.toggle('open');if(a==='sidebar')document.getElementById('sidebar')?.classList.toggle('open');if(a==='close-modal')document.getElementById('modalback')?.remove();if(a==='new-project')createProject();if(a==='create-model')go('create-model');if(a==='new-threat')createThreat();if(a==='save-node'){let n=model()?.nodes.find(x=>x.id===selectedNode);if(n){n.name=document.getElementById('node-name').value.trim()||n.name;n.kind=document.getElementById('node-type').value;n.data=document.getElementById('node-data').value;n.entry=document.getElementById('node-entry').value;n.notes=document.getElementById('node-notes').value;save();log(`Updated component ${n.name}`);render();toast('Component saved in this browser')}}if(a==='delete-node'){let m=model(),n=m?.nodes.find(x=>x.id===selectedNode);if(n&&confirm(`Delete “${n.name}” and its connected flows?`)){m.nodes=m.nodes.filter(x=>x.id!==n.id);m.flows=m.flows.filter(f=>f.from!==n.id&&f.to!==n.id);state.threats=state.threats.filter(t=>t.component!==n.name);selectedNode=m.nodes[0]?.id;save();log(`Deleted component ${n.name}`);render();toast('Component deleted')}}if(a==='add-flow'){let m=model();if(!m||m.nodes.length<2){toast('Add at least two components first');return}showModal(`<div class="modalhead"><div><h2>Add data flow</h2><p>Connect two components across a system boundary.</p></div><button class="iconbtn" data-action="close-modal">×</button></div><form class="form" id="generic-form" data-form-action="flow"><label>From</label><select name="from">${m.nodes.map(n=>`<option value="${n.id}">${esc(n.name)}</option>`).join('')}</select><label>To</label><select name="to">${m.nodes.map((n,i)=>`<option value="${n.id}" ${i===1?'selected':''}>${esc(n.name)}</option>`).join('')}</select><label>Protocol / data</label><input name="label" required placeholder="e.g. HTTPS / JSON"><div class="modalactions"><button type="button" class="btn" data-action="close-modal">Cancel</button><button class="btn primary">Add flow</button></div></form>`)}if(a==='add-boundary'){toast('The example application trust boundary is shown on the canvas. Boundary editing is planned.')}if(a==='save-model'){save();log(`Saved model ${model()?.name}`);toast('Model saved in this browser')}if(a==='analyze'){if(!model())return toast('Create a model first');if(!confirm('Run the disclosed local demo rules? These produce example suggestions only; no AI provider is connected.'))return;let existing=new Set(state.threats.map(t=>t.title));let prompts=[['Potential spoofing of a system identity','Spoofing','Review identity verification at exposed entry points.'],['Untrusted data may be modified in transit','Tampering','Validate data integrity and authorization at trust boundaries.'],['Sensitive data may be exposed across a boundary','Information Disclosure','Review data minimization, access checks, and transport controls.'],['Service capacity may be exhausted','Denial of Service','Review rate limits, timeouts, and resource safeguards.'],['Component may have excessive privileges','Elevation of Privilege','Review least privilege and role boundaries.'],['Critical actions may lack attribution','Repudiation','Review audit event coverage for sensitive actions.']];let created=0;for(let [title,category,mitigation] of prompts){if(existing.has(title))continue;let node=model().nodes.find(n=>n.kind!=='External entity')||model().nodes[0];let t={id:id('T'),title,category,component:node?.name||'System level',description:`Deterministic demonstration prompt for ${category}. Validate this scenario against the actual architecture before accepting it.`,scenario:`Review whether an attacker can exploit ${category.toLowerCase()} risks through the modeled system paths.`,impact:'Potential confidentiality, integrity, or availability impact depends on system context.',likelihood:2,impactScore:3,severity:'Medium',status:'Open',owner:'Unassigned',mitigation,sample:true};t.severity=sev(score(t));state.threats.push(t);created++}save();log(`Ran local demonstration rules; ${created} example suggestion(s) added`);go('threats');toast(`${created} deterministic demo suggestion(s) added`)}if(a==='export-csv'){download('nexguard-threat-register.csv','text/csv;charset=utf-8',csv());toast('CSV report downloaded')}if(a==='export-json'){download('nexguard-threat-model.json','application/json',JSON.stringify({generatedAt:new Date().toISOString(),demo:true,workspace:state.workspace,project:project(),model:model(),threats:state.threats},null,2));toast('JSON report downloaded')}if(a==='save-settings'){state.user.name=document.getElementById('setting-name').value.trim()||state.user.name;state.workspace=document.getElementById('setting-workspace').value.trim()||state.workspace;save();log('Updated profile and workspace settings');render();toast('Settings saved in this browser')}if(a==='dismiss-threat'){let t=state.threats.find(x=>x.id===el.dataset.id);if(t&&confirm('Dismiss this finding from the active register?')){t.status='Dismissed';save();log(`Dismissed threat ${t.id}`);document.getElementById('modalback')?.remove();render();toast('Threat dismissed')}}if(a==='account-info')go('accounts');if(a==='clear-data'&&confirm('Delete all projects, models, threats, and activity saved in this browser? This cannot be undone.')){state.projects=[];state.models=[];state.threats=[];state.activity=[];activeModelId=null;selectedNode=null;save();render();toast('Workspace data cleared')}if(a==='profile')go('settings');if(a==='workspace')toast(`Workspace: ${state.workspace} · browser demo data`);return}if(el.dataset.threat){openThreat(el.dataset.threat);return}if(el.dataset.node){selectedNode=el.dataset.node;render();return}if(el.dataset.template){createFromTemplate(el.dataset.template);return}if(el.dataset.createMode){if(el.dataset.createMode==='template'){go('templates')}else{showModal(`<div class="modalhead"><div><h2>Create threat model</h2><p>Give your system a scope before mapping it.</p></div><button class="iconbtn" data-action="close-modal">×</button></div><form class="form" id="generic-form" data-form-action="model"><label>Model name</label><input name="name" required minlength="2" placeholder="e.g. Checkout service"><label>Project</label><select name="projectId">${state.projects.map(p=>`<option value="${p.id}">${esc(p.name)}</option>`).join('')}</select><label>System description / scope</label><textarea name="description" required minlength="10" placeholder="What does this system do, and what is in scope?"></textarea><label>Technology stack</label><input name="stack" placeholder="Optional"><label>Environment</label><select name="environment"><option>Production</option><option>Staging</option><option>Development</option><option>Not specified</option></select><label>Starting point</label><select name="template"><option>Blank model</option>${state.templates.map(x=>`<option>${esc(x)}</option>`).join('')}</select><div class="modalactions"><button type="button" class="btn" data-action="close-modal">Cancel</button><button class="btn primary">Create model</button></div></form>`)}return}if(el.dataset.projectOpen){let p=state.projects.find(x=>x.id===el.dataset.projectOpen);let ms=state.models.filter(x=>x.projectId===p.id);showModal(`<div class="modalhead"><div><span class="eyebrow">PROJECT</span><h2>${esc(p.name)}</h2><p>${esc(p.description||'No description')}</p></div><button class="iconbtn" data-action="close-modal">×</button></div><div class="card"><div class="mono muted">${esc(p.stack||'STACK NOT SET')}</div><p style="margin-top:11px">${ms.length} model(s) · ${state.threats.length} threat record(s)</p></div><h3>Threat models</h3>${ms.map(m=>`<div class="flow-row"><span>${esc(m.name)}</span><button class="btn small" data-open-model="${m.id}">Open ↗</button></div>`).join('')||'<p class="muted">No models in this project.</p>'}<div class="modalactions"><button class="btn" data-action="project-archive" data-id="${p.id}">Archive</button><button class="btn" data-action="project-delete" data-id="${p.id}">Delete</button><button class="btn primary" data-create-project-model="${p.id}">＋ New model</button></div>`);return}if(el.dataset.openModel){activeModelId=el.dataset.openModel;selectedNode=null;document.getElementById('modalback')?.remove();go('architecture');return}if(el.dataset.createProjectModel){let pid=el.dataset.createProjectModel;document.getElementById('modalback')?.remove();openModelForm(pid);return}if(el.dataset.projectMenu){let p=state.projects.find(x=>x.id===el.dataset.projectMenu);if(p&&confirm(`Archive project “${p.name}”? Models and threats remain in your browser workspace.`)){p.status='Archived';save();log(`Archived project ${p.name}`);render();toast('Project archived')}return}if(el.dataset.deleteFlow!==undefined){let m=model();let f=m.flows.splice(Number(el.dataset.deleteFlow),1)[0];save();log(`Removed data flow ${f?.label||''}`);render();toast('Data flow removed');return}}
);
function openModelForm(pid){showModal(`<div class="modalhead"><div><h2>Create threat model</h2><p>Set the scope for your project.</p></div><button class="iconbtn" data-action="close-modal">×</button></div><form class="form" id="generic-form" data-form-action="model"><label>Model name</label><input name="name" required minlength="2" placeholder="e.g. Checkout service"><input type="hidden" name="projectId" value="${pid}"><label>System description / scope</label><textarea name="description" required minlength="10"></textarea><label>Technology stack</label><input name="stack" placeholder="Optional"><div class="modalactions"><button type="button" class="btn" data-action="close-modal">Cancel</button><button class="btn primary">Create model</button></div></form>`)}
function createFromTemplate(name){let p=state.projects[0];if(!p){createProject();return}let m=structuredClone(SEED.models[0]);m.id=id('M');m.projectId=p.id;m.name=`${name} — example`;m.description=`Illustrative ${name} template duplicated into ${p.name}. Replace sample components and findings with verified system details.`;m.created=new Date().toISOString().slice(0,10);m.nodes=m.nodes.map(n=>({...n,id:id('N')}));let old=SEED.models[0];m.flows=m.flows.map(f=>({...f,from:m.nodes[old.nodes.findIndex(n=>n.id===f.from)].id,to:m.nodes[old.nodes.findIndex(n=>n.id===f.to)].id}));state.models.push(m);activeModelId=m.id;save();log(`Duplicated ${name} sample template`);go('architecture');toast('Example template duplicated. Review sample data.')}
document.addEventListener('submit',e=>{if(e.target.id==='generic-form'){e.preventDefault();let f=e.target,fd=new FormData(f),d=Object.fromEntries(fd.entries()),action=f.dataset.formAction;if(action==='project'){let p={id:id('P'),name:d.name.trim(),description:d.description,stack:d.stack,updated:'Just now',status:'Active',sample:false};state.projects.unshift(p);save();log(`Created project ${p.name}`);document.getElementById('modalback')?.remove();render();toast('Project saved in this browser')}if(action==='model'){let m={id:id('M'),projectId:d.projectId||state.projects[0]?.id,name:d.name.trim(),description:d.description,created:new Date().toISOString().slice(0,10),nodes:[],flows:[]};state.models.unshift(m);activeModelId=m.id;save();log(`Created threat model ${m.name}`);document.getElementById('modalback')?.remove();go('architecture');toast('Threat model created')}if(action==='threat'){let t={...d,id:id('T'),likelihood:Number(d.likelihood),impactScore:Number(d.impactScore),status:'Open',sample:false,owner:d.owner||'Unassigned'};t.severity=sev(score(t));state.threats.unshift(t);save();log(`Added threat ${t.id}: ${t.title}`);document.getElementById('modalback')?.remove();render();toast('Threat saved in this browser')}if(action==='flow'){if(d.from===d.to){toast('Choose two different components');return}model().flows.push(d);save();document.getElementById('modalback')?.remove();render();toast('Data flow added')}}if(e.target.id==='threat-edit'){e.preventDefault();let t=state.threats.find(x=>x.id===e.target.dataset.id),d=Object.fromEntries(new FormData(e.target).entries());if(t){Object.assign(t,d,{likelihood:Number(d.likelihood),impactScore:Number(d.impactScore)});t.severity=sev(score(t));save();log(`Updated threat ${t.id}`);document.getElementById('modalback')?.remove();render();toast('Threat saved in this browser')}}if(e.target.id==='contact-form'){e.preventDefault();document.getElementById('form-status').textContent='Form validation passed. No submission was sent because no contact service is configured.'}});
document.addEventListener('input',e=>{if(e.target.id==='threat-search'){threatSearch=e.target.value;let start=window.scrollY;render();document.getElementById('threat-search')?.focus();document.getElementById('threat-search')?.setSelectionRange(threatSearch.length,threatSearch.length);window.scrollTo(0,start)}if(e.target.id==='project-search'){let q=e.target.value.toLowerCase();document.querySelectorAll('.project-card').forEach(c=>c.classList.toggle('hidden',!c.dataset.name.includes(q)))}if(e.target.id==='resource-search'){let q=e.target.value.toLowerCase();document.querySelectorAll('.resource').forEach(c=>c.classList.toggle('hidden',!c.dataset.search.includes(q)))}if(e.target.id==='global-search'){let q=e.target.value.trim();if(q.length>1){threatSearch=q;go('threats')}}if(e.target.closest('#threat-edit')&&['likelihood','impactScore'].includes(e.target.name)){let fd=new FormData(e.target.form),n=Number(fd.get('likelihood'))*Number(fd.get('impactScore'));document.getElementById('score-label').textContent=`${n} / 25 · ${sev(n)}`}});
document.addEventListener('change',e=>{if(e.target.id==='threat-filter'){threatFilter=e.target.value;render()}if(e.target.id==='model-switch'){activeModelId=e.target.value;selectedNode=null;render()}if(e.target.id==='threat-sort'){let sort=e.target.value;if(sort==='name')state.threats.sort((a,b)=>a.title.localeCompare(b.title));else state.threats.sort((a,b)=>score(b)-score(a));render()}if(e.target.id==='project-sort'){state.projects.sort((a,b)=>e.target.value==='name'?a.name.localeCompare(b.name):0);render()}if(e.target.matches('.status-change')){let t=state.threats.find(x=>x.id===e.target.dataset.statusId);if(t){t.status=e.target.value;save();log(`Changed mitigation status for ${t.id} to ${t.status}`);toast('Mitigation status saved in this browser')}}});
document.addEventListener('dragstart',e=>{let n=e.target.closest('.canvas-node');if(n)e.dataTransfer.setData('text/plain',n.dataset.node)});document.addEventListener('dragover',e=>{if(e.target.closest('#canvas'))e.preventDefault()});document.addEventListener('drop',e=>{let c=e.target.closest('#canvas');if(!c)return;e.preventDefault();let nid=e.dataTransfer.getData('text/plain'),n=model()?.nodes.find(x=>x.id===nid),r=c.getBoundingClientRect();if(n){n.x=Math.max(1,Math.min(82,(e.clientX-r.left)/r.width*100-5));n.y=Math.max(2,Math.min(82,(e.clientY-r.top)/r.height*100-4));selectedNode=n.id;save();render()}});
document.addEventListener('click',e=>{let a=e.target.closest('[data-open-model],[data-create-project-model]');if(a){if(a.dataset.openModel){activeModelId=a.dataset.openModel;document.getElementById('modalback')?.remove();go('architecture')}else{document.getElementById('modalback')?.remove();openModelForm(a.dataset.createProjectModel)}return}let action=e.target.closest('[data-action]');if(action?.dataset.action==='project-archive'){let p=state.projects.find(x=>x.id===action.dataset.id);if(p)p.status='Archived';save();document.getElementById('modalback')?.remove();render();toast('Project archived')}if(action?.dataset.action==='project-delete'){let p=state.projects.find(x=>x.id===action.dataset.id);if(p&&confirm(`Permanently delete project “${p.name}”, its models, and related sample data?`)){let modelIds=state.models.filter(m=>m.projectId===p.id).map(m=>m.id);state.projects=state.projects.filter(x=>x.id!==p.id);state.models=state.models.filter(m=>m.projectId!==p.id);if(!state.models.some(m=>m.id===activeModelId))activeModelId=state.models[0]?.id;save();log(`Deleted project ${p.name}`);document.getElementById('modalback')?.remove();render();toast('Project deleted from your account')}}});
window.addEventListener('hashchange',()=>{threatFilter='All';threatSearch='';render()});render();
document.addEventListener('click',e=>{let add=e.target.closest('[data-add-node]');if(add){let m=model();if(!m){toast('Create a model first');return}let type=add.dataset.addNode;if(type==='Data flow'){toast('Use “Add flow” to connect two components');return}let icons={'Process':'⌘','External entity':'◉','Data store':'▤'};let n={id:id('N'),name:type==='Process'?'New service':type==='Data store'?'New data store':'External system',kind:type,icon:icons[type],x:Math.max(3,Math.min(78,25+m.nodes.length*11)),y:Math.max(5,Math.min(78,20+(m.nodes.length%4)*13)),data:'Internal',entry:'',notes:''};m.nodes.push(n);selectedNode=n.id;save();log(`Added ${type.toLowerCase()} component`);render();toast('Component added. Edit details in the inspector.')}});

const strideExamples=[
{label:'SPOOFING',title:'Can someone pretend to be trusted?',description:'An attacker pretends to be a trusted user or service.',example:'A stolen session token is replayed.',question:'How do we verify the identity and freshness of each session?'},
{label:'TAMPERING',title:'Can data be changed without permission?',description:'Data or code is altered without authorization.',example:'A caller changes an account identifier in a request.',question:'Where do we validate integrity and object-level authorization?'},
{label:'REPUDIATION',title:'Can an important action be denied?',description:'A person or service can deny an action when evidence is missing.',example:'A billing change has no attributable audit event.',question:'Which actions need an actor, timestamp, and reliable record?'},
{label:'INFORMATION DISCLOSURE',title:'Could sensitive information reach the wrong person?',description:'Information becomes visible to someone who should not see it.',example:'Personal data is written to broadly accessible logs.',question:'Where is sensitive data stored, transmitted, logged, or exposed?'},
{label:'DENIAL OF SERVICE',title:'Can a dependency or endpoint be overwhelmed?',description:'A service or resource is made unavailable to legitimate users.',example:'Unbounded sign-in requests consume service capacity.',question:'What limits, timeouts, and recovery paths protect availability?'},
{label:'ELEVATION OF PRIVILEGE',title:'Can a user or service gain excess access?',description:'A principal gains permissions beyond its intended role.',example:'A service account can modify unrelated customer records.',question:'Are permissions narrow and checked at every boundary?'}];
const workflowCopy={architecture:['START WITH THE SYSTEM','Make trust visible.','Map processes, external entities, data stores, and the flows between them. Mark where trust changes and what data needs protection.',['Editable components and labels','Data classification and entry points','Flows connected to the affected system parts']],threats:['EXPLORE WHAT COULD GO WRONG','Turn a concern into a scenario.','Connect each threat to a real component, a clear attacker path, and a potential impact. Keep examples separate from verified findings.',['Six STRIDE categories','Component-linked records','Attack scenario and potential impact']],risk:['MAKE THE ASSUMPTIONS VISIBLE','Discuss likelihood and impact.','Use a simple, transparent scale to help a team compare concerns. Record uncertainty and calibrate the score to your own context.',['Likelihood × impact scoring','Severity bands you can explain','Human review stays in the loop']],mitigations:['TRACK THE NEXT ACTION','Keep risk work moving.','Assign an owner, describe a control, and update the mitigation status as implementation progresses.',['Suggested controls linked to findings','Open, in progress, implemented, accepted','Residual risk remains visible']]};
const audienceCopy={developers:['FOR DEVELOPERS','Turn design questions into engineering work.','Capture the component, scenario, and mitigation while implementation details are fresh. Keep follow-up work attached to the threat record.',['Identify entry points and ownership','Describe a concrete attack scenario','Track control work through implementation']],security:['FOR SECURITY ENGINEERS','Review risks with enough context to act.','Use the architecture and data flows to challenge assumptions, assess impact, and keep the threat register consistent across reviews.',['Review STRIDE coverage','Prioritize with visible assumptions','Follow findings through mitigation']],architects:['FOR SECURITY ARCHITECTS','Make trust boundaries easier to discuss.','Bring system boundaries, data movement, and security assumptions into one view that teams can review together.',['Surface trust changes','Capture security requirements','Keep decisions traceable to components']],devsecops:['FOR DEVSECOPS TEAMS','Connect design review to remediation.','Give engineering teams a place to record security work and move mitigation status forward as services change.',['Create a repeatable review','Connect findings to owners','Revisit risk as architecture evolves']],enterprise:['FOR ENTERPRISE SECURITY TEAMS','Create a consistent starting point.','Use a shared structure for review conversations. Workspace permissions, collaboration, and enterprise controls still need backend implementation.',['Use a common STRIDE vocabulary','Document scope and decisions','Plan governance requirements']]};
document.addEventListener('click',e=>{const drop=e.target.closest('[data-action="nav-dropdown"]');if(drop){let menu=document.getElementById(drop.getAttribute('aria-controls'));let opening=!menu.classList.contains('open');document.querySelectorAll('.nav-menu').forEach(m=>m.classList.remove('open'));document.querySelectorAll('[data-action="nav-dropdown"]').forEach(b=>b.setAttribute('aria-expanded','false'));menu.classList.toggle('open',opening);drop.setAttribute('aria-expanded',String(opening));return}const menuBtn=e.target.closest('[data-action="menu"]');if(menuBtn){let nav=document.getElementById('publicnav'),opening=!nav.classList.contains('open');nav.classList.toggle('open',opening);menuBtn.setAttribute('aria-expanded',String(opening));menuBtn.setAttribute('aria-label',opening?'Close navigation':'Open navigation');menuBtn.textContent=opening?'×':'☰';return}if(e.target.closest('[data-action="open-demo-model"]')){activeModelId=state.models[0]?.id||'m1';go('architecture');return}const stride=e.target.closest('[data-stride]');if(stride){let i=Number(stride.dataset.stride),c=cats[i],d=strideExamples[i];document.querySelectorAll('.category-tab').forEach((b,j)=>{b.classList.toggle('active',j===i);b.setAttribute('aria-selected',String(j===i))});document.getElementById('stride-label').textContent=`CATEGORY ${String(i+1).padStart(2,'0')} / ${d.label}`;document.getElementById('stride-title').textContent=d.title;document.getElementById('stride-description').textContent=d.description;document.getElementById('stride-example').textContent=d.example;document.getElementById('stride-question').textContent=d.question;return}const wf=e.target.closest('[data-workflow]');if(wf){let d=workflowCopy[wf.dataset.workflow];document.querySelectorAll('.workflow-tab').forEach(b=>b.classList.toggle('active',b===wf));document.getElementById('workflow-kicker').textContent=d[0];document.getElementById('workflow-title').textContent=d[1];document.getElementById('workflow-description').textContent=d[2];document.getElementById('workflow-points').innerHTML=d[3].map(x=>`<li>${esc(x)}</li>`).join('');return}const aud=e.target.closest('[data-audience]');if(aud){let d=audienceCopy[aud.dataset.audience];document.querySelectorAll('.audience-tab').forEach(b=>b.classList.toggle('active',b===aud));document.getElementById('audience-kicker').textContent=d[0];document.getElementById('audience-title').textContent=d[1];document.getElementById('audience-description').textContent=d[2];document.getElementById('audience-checks').innerHTML=d[3].map(x=>`<div>✓ ${esc(x)}</div>`).join('')}});
document.addEventListener('click',e=>{if(!e.target.closest('.navgroup-wrap')){document.querySelectorAll('.nav-menu').forEach(m=>m.classList.remove('open'));document.querySelectorAll('[data-action="nav-dropdown"]').forEach(b=>b.setAttribute('aria-expanded','false'))}if(e.target.closest('#publicnav a')){document.getElementById('publicnav')?.classList.remove('open');let b=document.querySelector('[data-action="menu"]');if(b){b.setAttribute('aria-expanded','false');b.setAttribute('aria-label','Open navigation');b.textContent='☰'}}});
document.addEventListener('input',e=>{if(!e.target.matches('#likelihood-range,#impact-range'))return;let l=Number(document.getElementById('likelihood-range').value),i=Number(document.getElementById('impact-range').value),n=l*i,s=n>=16?'Critical':n>=10?'High':n>=5?'Medium':'Low',el=document.getElementById('risk-severity');document.getElementById('likelihood-value').value=l;document.getElementById('impact-value').value=i;document.getElementById('risk-score').textContent=n;el.textContent=s.toUpperCase();el.className=`badge ${s.toLowerCase()}`;document.getElementById('risk-title').textContent=s==='Critical'?'Critical review priority':s==='High'?'High discussion priority':s==='Medium'?'Moderate discussion priority':'Lower discussion priority';document.getElementById('risk-copy').textContent=s==='Critical'?'Escalate for prompt review and confirm whether immediate controls are needed.':s==='High'?'Consider a timely mitigation plan and confirm the assumptions with the system owner.':s==='Medium'?'Discuss treatment options and document assumptions or planned controls.':'Record the reasoning and revisit if system context or assumptions change.';document.querySelectorAll('[data-risk-cell]').forEach(cell=>cell.classList.toggle('matrix-selected',cell.dataset.riskCell===`${l}-${i}`))});
document.addEventListener('keydown',e=>{if(e.key==='Escape'){document.querySelectorAll('.nav-menu').forEach(m=>m.classList.remove('open'));document.querySelectorAll('[data-action="nav-dropdown"]').forEach(b=>b.setAttribute('aria-expanded','false'));document.getElementById('publicnav')?.classList.remove('open');let b=document.querySelector('[data-action="menu"]');if(b){b.setAttribute('aria-expanded','false');b.setAttribute('aria-label','Open navigation');b.textContent='☰'}}});
